/* Faster "Recently opened" in the navigator, run after the download_events table exists (its later shape with created_at, from the upload safety work). The navigator's recent list (GET /api/me/places) reads a buyer's last downloads by the ids of their own entitlements and orders, newest first; download_events only had indexes on the asset, the token and the time, so that read scanned the table. Two partial indexes, one per id, newest first. No rows change. Until it runs the list still works, only slower. Where download_events or one of its columns is missing it skips itself with a notice. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.download_events') IS NULL THEN RAISE NOTICE 'download lookup: there is no download_events table, nothing to do.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'download_events' AND column_name = 'created_at') THEN RAISE NOTICE 'download lookup: download_events has no created_at, nothing to do.'; RETURN; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'download_events' AND column_name = 'entitlement_id') THEN CREATE INDEX IF NOT EXISTS idx_download_events_entitlement_recent ON public.download_events (entitlement_id, created_at DESC) WHERE entitlement_id IS NOT NULL; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'download_events' AND column_name = 'order_id') THEN CREATE INDEX IF NOT EXISTS idx_download_events_order_recent ON public.download_events (order_id, created_at DESC) WHERE order_id IS NOT NULL; END IF; END $do$;
notify pgrst, 'reload schema';
